    b.classList.toggle('pv-on', HtmlPreview.on());
    b.classList.toggle('dock-off', wide ? !Dock.open : !Dock.mOpen);
    b.classList.toggle('ws-off', !WS.shown || !chat || (wide && innerWidth < 900));   // 工作区悬浮，不再挤对话列，窄一些的窗口也能开
