  Bus.on('model', c => { try { const sid = c?.sid; if (sid) { UI._cards?.delete?.(sid); Titles?._viewMemo?.delete?.(sid); } UI.renderTabs?.(); UI.renderListSoon?.(50); } catch {} });
  Bus.on('modechange', () => { try { UI.renderList(); UI.renderTabs?.(); UI.showTab(); } catch {} });
