if (c.logoUrl) { const img = h('img', { src: c.logoUrl, alt: '', width: size, height: size, referrerpolicy: 'no-referrer' }); img.onerror = () => { img.remove(); box.textContent = (this.label(c.slug)[0] || '?').toUpperCase(); }; box.append(img); }
